package io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.app;
import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.web.bind.annotation.*;import io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.ConsumerFailureScenarioStarter;
@RestController@RequestMapping("/internal/takeover")@ConditionalOnProperty(name="scenario.takeover.enabled",havingValue="true")
public class TakeoverScenarioController {private final TakeoverExperiment experiment;private final TakeoverTracker tracker;private final String topic;public TakeoverScenarioController(TakeoverExperiment e,TakeoverTracker t,@Value("${app.kafka.topics.takeover}")String topic){experiment=e;tracker=t;this.topic=topic;}@GetMapping("/status")public TakeoverScenarioStatus status(){return ready("status");}@PostMapping("/reset")public TakeoverScenarioStatus reset(){tracker.reset();return ready("reset");}@PostMapping("/commands/{id}")public TakeoverScenarioStatus execute(@PathVariable String id,@RequestBody(required=false)TakeoverCommandRequest r){if(!ConsumerFailureScenarioStarter.OBSERVE_TAKEOVER.equals(id))throw new IllegalArgumentException("Unknown command: "+id);return experiment.run(r!=null&&r.invocationName()!=null?r.invocationName():id);}private TakeoverScenarioStatus ready(String n){return new TakeoverScenarioStatus("consumer-group-consumer-failure",n,true,true,true,false,false,null,null,-1,Map.of(),Map.of(),List.of(),List.of(),topic,null);}}
